import json

with open('batches/batch_0006.json', encoding='utf-8') as f:
    data = json.load(f)

def try_fix(s):
    if not s:
        return None
    try:
        return s.encode('latin1').decode('utf-8')
    except Exception:
        pass
    try:
        return s.encode('latin1', errors='replace').decode('utf-8', errors='replace')
    except Exception:
        pass
    return None

targets = [300,304,312,318,320,324,331,336,337,344,345]
for item in data:
    if item['idx'] in targets:
        print('='*30, item['idx'], item['name'])
        body_fixed = try_fix(item['body'])
        print(body_fixed[:1200] if body_fixed else None)
        print()
